        "source_handle": "P0517",
        "field_path": [
          "review_planning_B",
          "facet_contributions"
        ],
        "value": {
          "boundaries": "仅限于NSCLC人群；仅评估ICI单药治疗；未直接测量肠道菌群变化，而是通过抗生素使用作为菌群扰动的代理指标。",
          "contribution": "提供了抗生素使用对NSCLC患者ICI疗效影响的实证数据，证实了负面效应的存在，并量化了其对OS和PFS的具体影响幅度。",
          "facet_id": "F1"
        },
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::66a75b407fbfabec9a6931d8",
          "snapshot::8e39696d5d023f2a0efe55a9"
        ]
